      color: isSelected ? '#ffffff' : '#8899aa',
    }).setOrigin(0.5);
    btn.add(badgeText);

    // Label text
    const labelX = 28 + badgeSize + 16;
    const label = this.scene.add.text(labelX, 22, opt.label, {
      fontFamily: '"Segoe UI", system-ui, sans-serif',
