      }
    });
    btn.on('pointerout', () => {
      if (!isSelected) {
        bg.setFillStyle(C.btnNormal, 0.7);
        accentBar.setFillStyle(C.borderNormal, 0.3);
      }
    });
    btn.on('pointerdown', () => {
      // Tap scale micro-interaction
      this.scene.tweens.add({
        targets: btn,
        scaleX: 0.97,
        scaleY: 0.97,
        duration: 60,
        ease: EASE_TAP,
        yoyo: true,
        onComplete: () => this.toggleOption(opt.label),
      });
